1	"use client";
2	
3	import { useState, useEffect, useCallback } from "react";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Label } from "@/components/ui/label";
7	import { Textarea } from "@/components/ui/textarea";
8	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
9	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
10	import { Badge } from "@/components/ui/badge";
11	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
12	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
13	import { formatCurrency } from "@/lib/utils";
14	import { Plus, Edit, Trash2, Save, X, Eye, Receipt, DollarSign,
15	  Minus, AlertCircle, CheckCircle, Loader2, CreditCard, Banknote,
16	  ArrowLeft, ArrowRight, RefreshCw, FileText, Shield, AlertTriangle,
17	  ChevronDown, ChevronUp
18	} from "lucide-react";
19	import {
20	  BillingResponse,
21	  BillingItemResponse,
22	  PaymentResponse,
23	  BillingItemCreate,
24	  BillingItemUpdate,
25	  PaymentCreate,
26	  PaymentFormData,
27	  PaymentMethod,
28	  BillingStatus,
29	  PaymentStatus,
30	  BillingFormData,
31	  PAYMENT_METHOD_LABELS,
32	  PAYMENT_STATUS_LABELS,
33	  BILLING_STATUS_LABELS,
34	  DISCOUNT_TYPE_LABELS,
35	  DiscountType,
36	  BillingCalculationPreview,
37	} from "@/src/types/billing";
38	import { billingApi } from "@/lib/api";
39	
40	interface BillingManagerProps {
41	  shopId: number;
42	  applicationId: number;
43	  applicationNumber: string;
44	  serviceName: string;
45	  serviceBasePrice: number;
46	  customerName: string;
47	  canCreate: boolean;
48	  canUpdate: boolean;
49	  canDiscount: boolean;
50	  canCharge: boolean;
51	  canVoid: boolean;
52	  canPaymentCreate: boolean;
53	  canPaymentView: boolean;
54	  onBillingCreated?: () => void;
55	}
56	
57	export function BillingManager({
58	  shopId,
59	  applicationId,
60	  applicationNumber,
61	  serviceName,
62	  serviceBasePrice,
63	  customerName,
64	  canCreate,
65	  canUpdate,
66	  canDiscount,
67	  canCharge,
68	  canVoid,
69	  canPaymentCreate,
70	  canPaymentView,
71	  onBillingCreated,
72	}: BillingManagerProps) {
73	  const [loading, setLoading] = useState(true);
74	  const [error, setError] = useState<string | null>(null);
75	  const [billing, setBilling] = useState<BillingResponse | null>(null);
76	  const [payments, setPayments] = useState<PaymentResponse[]>([]);
77	  const [saving, setSaving] = useState(false);
78	  const [creating, setCreating] = useState(false);
79	  const [creatingPayment, setCreatingPayment] = useState(false);
80	  const [showCreateDialog, setShowCreateDialog] = useState(false);
81	  const [showEditDialog, setShowEditDialog] = useState(false);
82	  const [showPaymentDialog, setShowPaymentDialog] = useState(false);
83	  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
84	  const [editingItemId, setEditingItemId] = useState<number | null>(null);
85	  const [previewData, setPreviewData] = useState<BillingCalculationPreview | null>(null);
86	
87	  // Form states
88	  const [createForm, setCreateForm] = useState<BillingFormData>({
89	    items: [
90	      {
91	        name: serviceName,
92	        description: `Service: ${serviceName}`,
93	        amount: serviceBasePrice,
94	        is_service_item: true,
95	        service_id: undefined,
96	        sort_order: 0,
97	      },
98	    ],
99	    discount_type: undefined,
100	    discount_value: undefined,
101	    discount_reason: "",
102	    notes: "",
103	  });
104	
105	  const [editForm, setEditForm] = useState<Partial<BillingFormData>>({});
106	
107	  const [itemForm, setItemForm] = useState<BillingItemCreate>({
108	    name: "",
109	    description: "",
110	    amount: 0,
111	    is_service_item: false,
112	    service_id: undefined,
113	    sort_order: 0,
114	  });
115	
116	  const [paymentForm, setPaymentForm] = useState<PaymentFormData>({
117	    amount: 0,
118	    payment_method: "cash",
119	    reference_number: "",
120	    reference_exception: false,
121	    reference_exception_reason: "",
122	    notes: "",
123	  });
124	
125	  const isDigitalPayment = (method: PaymentMethod) =>
126	    method !== "cash";
127	
128	  const requiresReference = (method: PaymentMethod) =>
129	    isDigitalPayment(method);
130	
131	  const fetchBilling = useCallback(async () => {
132	    setLoading(true);
133	    setError(null);
134	    try {
135	      const data = await billingApi.getBilling(shopId, applicationId);
136	      setBilling(data);
137	    } catch (err) {
138	      setError(err instanceof Error ? err.message : "An error occurred");
139	    } finally {
140	      setLoading(false);
141	    }
142	  }, [shopId, applicationId]);
143	
144	  const fetchPayments = useCallback(async () => {
145	    if (!billing) return;
146	    try {
147	      const data = await billingApi.listPayments(shopId, billing.id);
148	      setPayments(data.items);
149	    } catch (err) {
150	      console.error("Failed to fetch payments:", err);
151	    }
152	  }, [shopId, billing]);
153	
154	  useEffect(() => {
155	    fetchBilling();
156	  }, [fetchBilling]);
157	
158	  useEffect(() => {
159	    fetchPayments();
160	  }, [fetchPayments]);
161	
162	  const handlePreviewCalculation = async () => {
163	    if (createForm.items.length === 0) return;
164	    try {
165	      const data = await billingApi.previewBilling(shopId, {
166	        items: createForm.items,
167	        discount_type: createForm.discount_type,
168	        discount_value: createForm.discount_value,
169	      });
170	      setPreviewData(data);
171	      setShowPreviewDialog(true);
172	    } catch (err) {
173	      console.error("Failed to preview calculation:", err);
174	    }
175	  };
176	
177	  const handleCreateBilling = async () => {
178	    if (createForm.items.length === 0) {
179	      setError("At least one line item is required");
180	      return;
181	    }
182	    if (createForm.discount_type && createForm.discount_value && !createForm.discount_reason) {
183	      setError("Discount reason is required");
184	      return;
185	    }
186	    setCreating(true);
187	    setError(null);
188	    try {
189	      const data = await billingApi.createBilling(shopId, applicationId, {
190	        application_id: applicationId,
191	        ...createForm,
192	      });
193	      setBilling(data);
194	      setShowCreateDialog(false);
195	      onBillingCreated?.();
196	    } catch (err) {
197	      setError(err instanceof Error ? err.message : "An error occurred");
198	    } finally {
199	      setCreating(false);
200	    }
201	  };
202	
203	  const handleUpdateBilling = async () => {
204	    if (!billing) return;
205	    setSaving(true);
206	    setError(null);
207	    try {
208	      const data = await billingApi.updateBilling(shopId, billing.id, editForm);
209	      setBilling(data);
210	      setShowEditDialog(false);
211	    } catch (err) {
212	      setError(err instanceof Error ? err.message : "An error occurred");
213	    } finally {
214	      setSaving(false);
215	    }
216	  };
217	
218	  const handleAddItem = async () => {
219	    if (!billing || itemForm.name.trim() === "" || itemForm.amount <= 0) return;
220	    setSaving(true);
221	    try {
222	      const data = await billingApi.addBillingItem(shopId, billing.id, itemForm);
223	      setBilling(prev => prev ? { ...prev, items: [...prev.items, data] } : null);
224	      setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 });
225	    } catch (err) {
226	      setError(err instanceof Error ? err.message : "An error occurred");
227	    } finally {
228	      setSaving(false);
229	    }
230	  };
231	
232	  const handleUpdateItem = async () => {
233	    if (!billing || editingItemId === null) return;
234	    setSaving(true);
235	    try {
236	      const data = await billingApi.updateBillingItem(shopId, billing.id, editingItemId, itemForm);
237	      setBilling(prev => prev ? {
238	        ...prev,
239	        items: prev.items.map(i => i.id === editingItemId ? data : i)
240	      } : null);
241	      setEditingItemId(null);
242	    } catch (err) {
243	      setError(err instanceof Error ? err.message : "An error occurred");
244	    } finally {
245	      setSaving(false);
246	    }
247	  };
248	
249	  const handleDeleteItem = async (itemId: number) => {
250	    if (!billing || !confirm("Delete this line item?")) return;
251	    setSaving(true);
252	    try {
253	      await billingApi.deleteBillingItem(shopId, billing.id, itemId);
254	      setBilling(prev => prev ? { ...prev, items: prev.items.filter(i => i.id !== itemId) } : null);
255	    } catch (err) {
256	      setError(err instanceof Error ? err.message : "An error occurred");
257	    } finally {
258	      setSaving(false);
259	    }
260	  };
261	
262	  const startEditItem = (item: BillingItemResponse) => {
263	    setItemForm({
264	      name: item.name,
265	      description: item.description || "",
266	      amount: item.amount,
267	      is_service_item: item.is_service_item,
268	      service_id: item.service_id,
269	      sort_order: item.sort_order,
270	    });
271	    setEditingItemId(item.id);
272	  };
273	
274	  const handleCreatePayment = async () => {
275	    if (!billing) return;
276	    if (paymentForm.amount <= 0) {
277	      setError("Payment amount must be greater than zero");
278	      return;
279	    }
280	    if (paymentForm.amount > (billing.balance_amount || 0)) {
281	      setError("Payment amount exceeds outstanding balance");
282	      return;
283	    }
284	    if (requiresReference(paymentForm.payment_method) && !paymentForm.reference_exception && !paymentForm.reference_number?.trim()) {
285	      setError("Reference number is required for digital payments");
286	      return;
287	    }
288	    if (paymentForm.reference_exception && !paymentForm.reference_exception_reason?.trim()) {
289	      setError("Exception reason is required when reference is unavailable");
290	      return;
291	    }
292	    setCreatingPayment(true);
293	    setError(null);
294	    try {
295	      const data = await billingApi.createPayment(shopId, billing.id, paymentForm);
296	      setPayments(prev => [...prev, data]);
297	      setBilling(prev => prev ? {
298	        ...prev,
299	        amount_paid: data.amount + (prev.amount_paid || 0),
300	        balance_amount: Math.max(0, (prev.balance_amount || 0) - data.amount),
301	        payment_status: data.amount + (prev.amount_paid || 0) >= (prev.total_amount || 0) ? "paid" :
302	          data.amount + (prev.amount_paid || 0) > 0 ? "partially_paid" : "unpaid",
303	      } : null);
304	      setShowPaymentDialog(false);
305	      setPaymentForm({ amount: 0, payment_method: "cash", reference_number: "", reference_exception: false, reference_exception_reason: "", notes: "" });
306	    } catch (err) {
307	      setError(err instanceof Error ? err.message : "An error occurred");
308	    } finally {
309	      setCreatingPayment(false);
310	    }
311	  };
312	
313	  const handleIssueBilling = async () => {
314	    if (!billing || !confirm("Issue this billing? This will change status from Draft to Issued.")) return;
315	    setSaving(true);
316	    try {
317	      const data = await billingApi.issueBilling(shopId, billing.id);
318	      setBilling(data);
319	    } catch (err) {
320	      setError(err instanceof Error ? err.message : "An error occurred");
321	    } finally {
322	      setSaving(false);
323	    }
324	  };
325	
326	  const handleVoidBilling = async () => {
327	    if (!billing || !confirm("Void this billing? This action cannot be undone.")) return;
328	    setSaving(true);
329	    try {
330	      const data = await billingApi.voidBilling(shopId, billing.id);
331	      setBilling(data);
332	    } catch (err) {
333	      setError(err instanceof Error ? err.message : "An error occurred");
334	    } finally {
335	      setSaving(false);
336	    }
337	  };
338	
339	  const getStatusBadge = (status: string, type: "billing" | "payment") => {
340	    if (type === "billing") {
341	      const config: Record<BillingStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
342	        draft: { variant: "secondary", label: "Draft" },
343	        issued: { variant: "default", label: "Issued" },
344	        void: { variant: "destructive", label: "Void" },
345	      };
346	      const c = config[status as BillingStatus] || { variant: "secondary", label: status };
347	      return <Badge variant={c.variant}>{c.label}</Badge>;
348	    } else {
349	      const config: Record<PaymentStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
350	        unpaid: { variant: "destructive", label: "Unpaid" },
351	        partially_paid: { variant: "warning", label: "Partially Paid" },
352	        paid: { variant: "success", label: "Paid" },
353	      };
354	      const c = config[status as PaymentStatus] || { variant: "secondary", label: status };
355	      return <Badge variant={c.variant}>{c.label}</Badge>;
356	    }
357	  };
358	
359	  const paymentMethodLabel = (method: PaymentMethod) =>
360	    PAYMENT_METHOD_LABELS.find(l => l.value === method)?.label || method;
361	
362	  const isDigital = (method: PaymentMethod) => isDigitalPayment(method);
363	
364	  if (loading) {
365	    return (
366	      <Card className="mt-6">
367	        <CardContent className="py-8 text-center">
368	          <Loader2 className="h-8 w-8 animate-spin text-primary mx-auto mb-2" />
369	          <p className="text-muted-foreground">Loading billing...</p>
370	        </CardContent>
371	      </Card>
372	    );
373	  }
374	
375	  if (error) {
376	    return (
377	      <Card className="mt-6 border-destructive">
378	        <CardContent className="p-4 text-destructive">
379	          <AlertCircle className="h-5 w-5 mr-2 inline" />
380	          {error}
381	        </CardContent>
382	      </Card>
383	    );
384	  }
385	
386	  if (!billing) {
387	    if (!canCreate) {
388	      return (
389	        <Card className="mt-6">
390	          <CardContent className="py-8 text-center">
391	            <FileText className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
392	            <h3 className="text-lg font-medium mb-2">No Billing Record</h3>
393	            <p className="text-muted-foreground mb-4">Create a billing record to track payments for this application.</p>
394	          </CardContent>
395	        </Card>
396	      );
397	    }
398	
399	    return (
400	      <Card className="mt-6">
401	        <CardHeader>
402	          <CardTitle className="flex items-center gap-2">
403	            <DollarSign className="h-5 w-5" />
404	            Create Billing for {applicationNumber}
405	          </CardTitle>
406	          <CardDescription>Set up invoice with service amount, additional charges, and discounts</CardDescription>
407	        </CardHeader>
408	        <CardContent className="space-y-6">
409	          {/* Service Item (non-editable price) */}
410	          <div className="bg-muted/50 p-4 rounded-lg border">
411	            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-2">
412	              <Shield className="h-4 w-4" />
413	              <span>Service price is loaded from service configuration and cannot be freely edited</span>
414	            </div>
415	            <div className="grid gap-4 sm:grid-cols-3">
416	              <div className="sm:col-span-2">
417	                <Label className="text-xs text-muted-foreground">Service</Label>
418	                <Input value={serviceName} disabled />
419	              </div>
420	              <div>
421	                <Label className="text-xs text-muted-foreground">Base Price</Label>
422	                <Input value={formatCurrency(serviceBasePrice)} disabled />
423	              </div>
424	            </div>
425	          </div>
426	
427	          {/* Line Items */}
428	          <div>
429	            <div className="flex items-center justify-between mb-3">
430	              <Label>Line Items</Label>
431	              <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
432	                <DialogTrigger asChild>
433	                  <Button size="sm"><Plus className="h-4 w-4 mr-1" /> Add Charge</Button>
434	                </DialogTrigger>
435	                <DialogContent>
436	                  <DialogHeader>
437	                    <DialogTitle>Add Additional Charge</DialogTitle>
438	                  </DialogHeader>
439	                  <div className="space-y-4 py-4">
440	                    <div className="space-y-2">
441	                      <Label htmlFor="item-name">Charge Name</Label>
442	                      <Input
443	                        id="item-name"
444	                        value={itemForm.name}
445	                        onChange={e => setItemForm(prev => ({ ...prev, name: e.target.value }))}
446	                        placeholder="e.g., Printing, Courier, Service Fee"
447	                      />
448	                    </div>
449	                    <div className="space-y-2">
450	                      <Label htmlFor="item-description">Description (Optional)</Label>
451	                      <Textarea
452	                        id="item-description"
453	                        value={itemForm.description}
454	                        onChange={e => setItemForm(prev => ({ ...prev, description: e.target.value }))}
455	                        rows={2}
456	                      />
457	                    </div>
458	                    <div className="grid gap-4 sm:grid-cols-2">
459	                      <div className="space-y-2">
460	                        <Label htmlFor="item-amount">Amount</Label>
461	                        <Input
462	                          id="item-amount"
463	                          type="number"
464	                          step="0.01"
465	                          min="0"
466	                          value={itemForm.amount}
467	                          onChange={e => setItemForm(prev => ({ ...prev, amount: parseFloat(e.target.value) || 0 }))}
468	                        />
469	                      </div>
470	                      <div className="space-y-2">
471	                        <Label>Type</Label>
472	                        <Select value={itemForm.is_service_item ? "service" : "charge"} onValueChange={v => setItemForm(prev => ({ ...prev, is_service_item: v === "service" }))}>
473	                          <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
474	                          <SelectContent>
475	                            <SelectItem value="charge">Non-Service Charge</SelectItem>
476	                            <SelectItem value="service">Service Item</SelectItem>
477	                          </SelectContent>
478	                        </Select>
479	                      </div>
480	                    </div>
481	                    <div className="flex justify-end gap-2 pt-4 border-t">
482	                      <Button variant="outline" onClick={() => { setShowCreateDialog(false); setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 }); }}>Cancel</Button>
483	                      <Button onClick={handleAddItem} disabled={saving || itemForm.name.trim() === "" || itemForm.amount <= 0}>{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Add"}</Button>
484	                    </div>
485	                  </div>
486	                </DialogContent>
487	              </Dialog>
488	            </div>
489	            {createForm.items.map((item, index) => (
490	              <div key={index} className="flex items-center gap-3 p-3 border rounded-lg bg-background mb-2">
491	                <div className="flex-1 min-w-0">
492	                  <p className="font-medium">{item.name} {item.is_service_item && <Badge variant="secondary" className="ml-2 text-xs">Service</Badge>}</p>
493	                  {item.description && <p className="text-sm text-muted-foreground">{item.description}</p>}
494	                </div>
495	                <div className="font-mono text-right whitespace-nowrap">{formatCurrency(item.amount)}</div>
496	                {index > 0 && (
497	                  <Button variant="ghost" size="icon" onClick={() => {
498	                    const newItems = [...createForm.items];
499	                    newItems.splice(index, 1);
500	                    setCreateForm(prev => ({ ...prev, items: newItems }));
501	                  }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
502	                )}
503	              </div>
504	            ))}
505	          </div>
506	
507	          {/* Discount */}
508	          <div>
509	            <Label>Discount</Label>
510	            <div className="grid gap-4 sm:grid-cols-3">
511	              <div className="space-y-2">
512	                <Label htmlFor="discount-type">Type</Label>
513	                <Select value={createForm.discount_type || ""} onValueChange={v => setCreateForm(prev => ({ ...prev, discount_type: v as DiscountType || undefined }))}>
514	                  <SelectTrigger><SelectValue placeholder="Select discount type" /></SelectTrigger>
515	                  <SelectContent>
516	                    <SelectItem value="fixed">Fixed Amount</SelectItem>
517	                    <SelectItem value="percentage">Percentage</SelectItem>
518	                  </SelectContent>
519	                </Select>
520	              </div>
521	              <div className="space-y-2">
522	                <Label htmlFor="discount-value">Value</Label>
523	                <Input
524	                  id="discount-value"
525	                  type="number"
526	                  step="0.01"
527	                  min="0"
528	                  value={createForm.discount_value || ""}
529	                  onChange={e => setCreateForm(prev => ({ ...prev, discount_value: parseFloat(e.target.value) || undefined }))}
530	                  placeholder={createForm.discount_type === "percentage" ? "e.g., 10" : "e.g., 50"}
531	                />
532	              </div>
533	              <div className="space-y-2">
534	                <Label htmlFor="discount-reason">Reason (Required)</Label>
535	                <Input
536	                  id="discount-reason"
537	                  value={createForm.discount_reason}
538	                  onChange={e => setCreateForm(prev => ({ ...prev, discount_reason: e.target.value }))}
539	                  placeholder="e.g., Student discount, Loyalty, Manager approval"
540	                />
541	              </div>
542	            </div>
543	          </div>
544	
545	          {/* Notes */}
546	          <div className="space-y-2">
547	            <Label htmlFor="notes">Internal Notes</Label>
548	            <Textarea
549	              id="notes"
550	              value={createForm.notes}
551	              onChange={e => setCreateForm(prev => ({ ...prev, notes: e.target.value }))}
552	              rows={3}
553	              placeholder="Optional internal notes..."
554	            />
555	          </div>
556	
557	          {/* Preview & Create */}
558	          <div className="flex gap-3 pt-4 border-t">
559	            <Button variant="outline" onClick={handlePreviewCalculation}><Eye className="h-4 w-4 mr-1" /> Preview</Button>
560	            <Button onClick={handleCreateBilling} disabled={creating} className="ml-auto">
561	              {creating ? <Loader2 className="h-4 w-4 animate-spin" /> : "Create Billing"}
562	            </Button>
563	          </div>
564	        </CardContent>
565	      </Card>
566	    );
567	  }
568	
569	  // Render existing billing
570	  return (
571	    <div className="mt-6 space-y-6">
572	      {/* Billing Header */}
573	      <Card>
574	        <CardHeader>
575	          <div className="flex items-center justify-between">
576	            <div>
577	              <CardTitle className="flex items-center gap-2">
578	                <DollarSign className="h-5 w-5" />
579	                Billing: {billing.invoice_number}
580	              </CardTitle>
581	              <CardDescription>Application: {applicationNumber} | Service: {serviceName} | Customer: {customerName}</CardDescription>
582	            </div>
583	            <div className="flex items-center gap-2">
584	              {getStatusBadge(billing.billing_status, "billing")}
585	              {getStatusBadge(billing.payment_status, "payment")}
586	            </div>
587	          </div>
588	        </CardHeader>
589	        <CardContent className="space-y-6">
590	          {/* Summary */}
