166	export async function login(
167	  email: string,
168	  password: string
169	): Promise<LoginResponse> {
170	  const res = await fetch(`${AUTH_PROXY}/login`, {
171	    method: "POST",
172	    headers: { "Content-Type": "application/json" },
173	    body: JSON.stringify({ email, password }),
174	    credentials: "include",
175	  });
176	  if (!res.ok) {
177	    const body = await res.json().catch(() => ({}));
178	    throw new ApiError(res.status, body?.error?.message ?? "Login failed");
179	  }
180	  const data: LoginResponse = await res.json();
181	  setAccessToken(data.access_token, data.expires_in);
182	  return data;
183	}
184	
185	export async function refreshToken(): Promise<LoginResponse | null> {
186	  const res = await fetch(`${AUTH_PROXY}/refresh`, {
187	    method: "POST",
188	    credentials: "include",
189	  });
190	  if (!res.ok) return null;
191	  const data: LoginResponse = await res.json();
192	  setAccessToken(data.access_token, data.expires_in);
193	  return data;
194	}
195	
196	export async function logout(): Promise<void> {
197	  await fetch(`${AUTH_PROXY}/logout`, {
198	    method: "POST",
199	    credentials: "include",
200	    headers: accessToken
201	      ? { Authorization: `Bearer ${accessToken}` }
202	      : undefined,
203	  });
204	  clearAccessToken();
205	}
206	
207	export async function fetchCurrentUser(): Promise<AuthUser> {
208	  const token = getAccessToken();
209	  if (!token) throw new ApiError(401, "Not authenticated");
210	  const res = await fetch(`${AUTH_PROXY}/me`, {
211	    headers: { Authorization: `Bearer ${token}` },
212	    credentials: "include",
213	  });
214	  if (!res.ok) throw new ApiError(res.status, "Failed to load user");
215	  return res.json();
216	}
