201	    };
202	    const config = statusConfigs[status] || { variant: "secondary", label: status };
203	    return <Badge variant={config.variant}>{config.label}</Badge>;
204	  };
205	
206	  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
207	    const { name, value, type } = e.target;
208	    const newValue = type === "checkbox" ? (e.target as HTMLInputElement).checked : value;
209	
210	    if (name === "assigned_staff_id") {
211	      const stringVal = value as string;
212	      setFormData(prev => ({ ...prev, [name]: stringVal === "" ? "" : parseInt(stringVal, 10) }));
213	    } else {
214	      setFormData(prev => ({ ...prev, [name]: newValue }));
215	    }
216	  };
217	
218	  const handleDynamicFieldChange = (fieldName: string, value: any) => {
219	    setFormData(prev => ({
220	      ...prev,
221	      application_data: { ...prev.application_data, [fieldName]: value },
222	    }));
223	  };
224	
225	  const handleSave = async () => {
226	    if (!shopId || !applicationId) return;
227	    setSaving(true);
228	    setError(null);
229	    try {
230	      const payload = {
231	        status: formData.status,
232	        assigned_staff_id: formData.assigned_staff_id || null,
233	        application_data: formData.application_data,
234	        notes: formData.notes || null,
235	      };
236	      const resp = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
237	        method: "PATCH",
238	        headers: {
239	          "Content-Type": "application/json",
240	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
241	        },
242	        body: JSON.stringify(payload),
243	      });
244	      if (!resp.ok) {
245	        const data = await resp.json();
246	        throw new Error(data.detail || "Failed to update application");
247	      }
248	      const updated = await resp.json();
249	      setApplication(updated);
250	      setEditMode(false);
251	    } catch (err) {
252	      setError(err instanceof Error ? err.message : "An error occurred");
253	    } finally {
254	      setSaving(false);
255	    }
256	  };
257	
258	  if (authLoading) {
259	    return (
260	      <div className="flex min-h-screen items-center justify-center">
261	        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
262	      </div>
263	    );
264	  }
265	
266	  if (loading) {
267	    return (
268	      <ProtectedRoute>
269	        <div className="container mx-auto py-8">
270	          <div className="flex items-center justify-center h-64">
271	            <Loader2 className="h-8 w-8 animate-spin text-primary" />
272	          </div>
273	        </div>
274	      </ProtectedRoute>
275	    );
276	  }
277	
278	  if (error) {
279	    return (
280	      <ProtectedRoute>
281	        <div className="container mx-auto py-8">
282	          <div className="text-center">
283	            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
284	            <h2 className="text-xl font-semibold mb-2">Failed to load application</h2>
285	            <p className="text-muted-foreground mb-4">{error}</p>
286	            <Button variant="outline" asChild>
287	              <Link href="/dashboard/applications">
288	                <ArrowLeft className="mr-2 h-4 w-4" />
289	                Back to Applications
290	              </Link>
291	            </Button>
292	          </div>
293	        </div>
294	      </ProtectedRoute>
295	    );
296	  }
297	
298	  if (!application) {
299	    return (
300	      <ProtectedRoute>
301	        <div className="container mx-auto py-8">
302	          <div className="text-center">
303	            <X className="h-12 w-12 text-destructive mx-auto mb-4" />
304	            <h2 className="text-xl font-semibold mb-2">Application not found</h2>
305	            <Button variant="outline" asChild>
306	              <Link href="/dashboard/applications">
307	                <ArrowLeft className="mr-2 h-4 w-4" />
308	                Back to Applications
309	              </Link>
310	            </Button>
311	          </div>
312	        </div>
313	      </ProtectedRoute>
314	    );
315	  }
316	
317	  const statusOrder: ApplicationStatus[] = ["enquiry", "applied", "documents_pending", "under_processing", "completed", "rejected", "cancelled"];
318	  const currentStatusIndex = statusOrder.indexOf(application.status);
319	
320	  return (
321	    <ProtectedRoute>
322	      <div className="container mx-auto py-8">
323	        <div className="flex items-center gap-4 mb-6">
324	          <Button variant="outline" size="icon" asChild>
325	            <Link href={`/dashboard/applications?shop_id=${shopId}`}>
326	              <ArrowLeft className="h-4 w-4" />
327	            </Link>
328	          </Button>
329	          <div className="flex-1">
330	            <h1 className="text-3xl font-bold tracking-tight">{application.application_number}</h1>
331	            <p className="text-muted-foreground mt-1">{application.service.name}</p>
332	          </div>
333	          <div className="flex items-center gap-2">
334	            {getStatusBadge(application.status)}
335	            <Button variant="outline" onClick={() => setEditMode(!editMode)}>
336	              {editMode ? <X className="h-4 w-4" /> : <Edit className="h-4 w-4" />}
337	              {editMode ? "Cancel" : "Edit"}
338	            </Button>
339	          </div>
340	        </div>
341	
342	        {error && (
343	          <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
344	            {error}
345	          </div>
346	        )}
347	
348	        {/* Status Timeline */}
349	        <Card className="mb-6">
350	          <CardHeader>
351	            <CardTitle>Status Timeline</CardTitle>
352	            <CardDescription>Track the progress of this application</CardDescription>
353	          </CardHeader>
354	          <CardContent>
355	            <div className="relative pl-4">
356	              <div className="absolute left-2 top-0 bottom-0 w-0.5 bg-muted" />
357	              {statusOrder.map((status, index) => {
358	                const isCompleted = index < currentStatusIndex;
359	                const isCurrent = index === currentStatusIndex;
360	                const isFuture = index > currentStatusIndex;
361	
362	                const statusConfigs: Record<ApplicationStatus, { label: string; icon: React.ReactNode }> = {
363	                  enquiry: { label: "Enquiry", icon: <span className="text-xs">1</span> },
364	                  applied: { label: "Applied", icon: <CheckCircle className="h-4 w-4" /> },
365	                  documents_pending: { label: "Documents Pending", icon: <AlertCircle className="h-4 w-4" /> },
366	                  under_processing: { label: "Under Processing", icon: <Loader2 className="h-4 w-4 animate-spin" /> },
367	                  completed: { label: "Completed", icon: <CheckCircle className="h-4 w-4 text-green-500" /> },
368	                  rejected: { label: "Rejected", icon: <X className="h-4 w-4 text-red-500" /> },
369	                  cancelled: { label: "Cancelled", icon: <X className="h-4 w-4 text-gray-500" /> },
370	                };
371	                const config = statusConfigs[status];
372	
373	                return (
374	                  <div key={status} className="relative flex items-start gap-4 pb-6 last:pb-0">
375	                    <div className={`flex h-8 w-8 items-center justify-center rounded-full border-2 shrink-0 relative z-10 ${
376	                      isCompleted ? "bg-primary border-primary text-primary-foreground" :
377	                      isCurrent ? "bg-primary border-primary text-primary-foreground" :
378	                      "bg-background border-muted text-muted-foreground"
379	                    }`}>
380	                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : config.icon}
381	                    </div>
382	                    <div className="flex-1 pt-1">
383	                      <p className={`font-medium ${isCurrent ? "text-foreground" : isCompleted ? "text-foreground" : "text-muted-foreground"}`}>
384	                        {config.label}
385	                      </p>
386	                      <p className="text-sm text-muted-foreground">
387	                        {isCompleted && application.updated_at && `Updated ${new Date(application.updated_at).toLocaleDateString()}`}
388	                      </p>
389	                    </div>
390	                  </div>
391	                );
392	              })}
393	            </div>
394	          </CardContent>
395	        </Card>
396	
397	        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
398	          {/* Customer Info */}
399	          <Card>
400	            <CardHeader>
401	              <CardTitle className="flex items-center gap-2">
402	                <Users className="h-5 w-5" />
403	                Customer
404	              </CardTitle>
405	            </CardHeader>
406	            <CardContent className="space-y-3">
407	              <div>
408	                <Label className="text-xs text-muted-foreground">Name</Label>
409	                <p className="font-medium">{application.customer.name}</p>
410	              </div>
411	              <div>
412	                <Label className="text-xs text-muted-foreground">Mobile</Label>
413	                <p className="font-mono">{application.customer.mobile}</p>
414	              </div>
415	              {application.customer.email && (
416	                <div>
417	                  <Label className="text-xs text-muted-foreground">Email</Label>
418	                  <p>{application.customer.email}</p>
419	                </div>
420	              )}
421	              {application.customer.address && (
422	                <div>
423	                  <Label className="text-xs text-muted-foreground">Address</Label>
424	                  <p className="text-sm">{application.customer.address}</p>
425	                </div>
426	              )}
427	              <div className="pt-2 border-t">
428	                <Button variant="outline" size="sm" asChild>
429	                  <Link href={`/dashboard/customers/${application.customer.id}?shop_id=${shopId}`}>
430	                    View Customer Profile
431	                  </Link>
432	                </Button>
433	              </div>
434	            </CardContent>
435	          </Card>
436	
437	          {/* Service Info */}
438	          <Card>
439	            <CardHeader>
440	              <CardTitle className="flex items-center gap-2">
441	                <Banknote className="h-5 w-5" />
442	                Service
443	              </CardTitle>
444	            </CardHeader>
445	            <CardContent className="space-y-3">
446	              <div>
447	                <Label className="text-xs text-muted-foreground">Name</Label>
448	                <p className="font-medium">{application.service.name}</p>
449	              </div>
450	              {application.service.description && (
451	                <div>
452	                  <Label className="text-xs text-muted-foreground">Description</Label>
453	                  <p className="text-sm">{application.service.description}</p>
454	                </div>
455	              )}
456	              <div>
457	                <Label className="text-xs text-muted-foreground">Base Price</Label>
458	                <p className="font-mono">{new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(application.service.base_price)}</p>
459	              </div>
460	              <div className="pt-2 border-t">
461	                <Button variant="outline" size="sm" asChild>
462	                  <Link href={`/dashboard/services/${application.service.id}?shop_id=${shopId}`}>
463	                    View Service Details
464	                  </Link>
465	                </Button>
466	              </div>
467	            </CardContent>
468	          </Card>
469	
470	          {/* Assigned Staff */}
471	          <Card>
472	            <CardHeader>
473	              <CardTitle className="flex items-center gap-2">
474	                <Users className="h-5 w-5" />
475	                Assigned Staff
476	              </CardTitle>
477	            </CardHeader>
478	            <CardContent>
479	              {application.assigned_staff ? (
480	                <div className="space-y-3">
481	                  <div className="flex items-center gap-3">
482	                    <div className="flex-shrink-0 h-10 w-10 rounded bg-muted/50 flex items-center justify-center">
483	                      <Users className="h-5 w-5 text-muted-foreground" />
484	                    </div>
485	                    <div>
486	                      <p className="font-medium">{application.assigned_staff.full_name}</p>
487	                      <p className="text-sm text-muted-foreground">{application.assigned_staff.email}</p>
488	                    </div>
489	                  </div>
490	                  {editMode && (
491	                    <div className="space-y-2">
492	                      <Label htmlFor="assigned_staff_id">Reassign Staff</Label>
493	                      <Select
494	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
495	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
496	                      >
497	                        <SelectTrigger>
498	                          <SelectValue placeholder="Select staff member" />
499	                        </SelectTrigger>
500	                        <SelectContent>
501	                          <SelectItem value="">Unassign</SelectItem>
502	                          {staff.map((s) => (
503	                            <SelectItem key={s.id} value={String(s.id)}>
504	                              {s.full_name} ({s.email})
505	                            </SelectItem>
506	                          ))}
507	                        </SelectContent>
508	                      </Select>
509	                    </div>
510	                  )}
511	                </div>
512	              ) : (
513	                <div className="space-y-3">
514	                  <p className="text-muted-foreground italic">No staff assigned</p>
515	                  {editMode && (
516	                    <div className="space-y-2">
517	                      <Label htmlFor="assigned_staff_id">Assign Staff</Label>
518	                      <Select
519	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
520	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
521	                      >
522	                        <SelectTrigger>
523	                          <SelectValue placeholder="Select staff member" />
524	                        </SelectTrigger>
525	                        <SelectContent>
526	                          {staff.map((s) => (
527	                            <SelectItem key={s.id} value={String(s.id)}>
528	                              {s.full_name} ({s.email})
529	                            </SelectItem>
530	                          ))}
531	                        </SelectContent>
532	                      </Select>
533	                    </div>
534	                  )}
535	                </div>
536	              )}
537	            </CardContent>
538	          </Card>
539	
540	          {/* Application Data */}
541	          {application.service.fields && application.service.fields.length > 0 && (
542	            <Card className="md:col-span-2 lg:col-span-3">
543	              <CardHeader>
544	                <CardTitle>Service Information</CardTitle>
545	              </CardHeader>
546	              <CardContent className="space-y-4">
547	                {application.service.fields.map((field) => {
548	                  const value = application.application_data?.[field.name];
549	                  const displayValue = value === undefined || value === null || value === ""
550	                    ? <span className="text-muted-foreground italic">Not provided</span>
551	                    : field.field_type === "boolean"
552	                      ? (value ? "Yes" : "No")
553	                      : field.field_type === "date"
554	                        ? new Date(value).toLocaleDateString()
555	                        : String(value);
556	
557	                  return (
558	                    <div key={field.id} className="space-y-1">
559	                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
560	                      {editMode ? (
561	                        <div>
562	                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
563	                            <Select
564	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
565	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
566	                            >
567	                              <SelectTrigger>
568	                                <SelectValue placeholder={`Select ${field.label}`} />
569	                              </SelectTrigger>
570	                              <SelectContent>
571	                                <SelectItem value="">Select...</SelectItem>
572	                                {field.options.map((opt) => (
573	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
574	                                ))}
575	                              </SelectContent>
576	                            </Select>
577	                          ) : field.field_type === "boolean" ? (
578	                            <div className="flex items-center gap-2">
579	                              <input
580	                                type="checkbox"
581	                                id={`edit-${field.name}`}
582	                                checked={formData.application_data[field.name] === true}
583	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
584	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
585	                              />
586	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
587	                                {field.label === "Yes" ? "Yes" : "Enabled"}
588	                              </Label>
589	                            </div>
590	                          ) : field.field_type === "textarea" ? (
591	                            <Textarea
592	                              id={`edit-${field.name}`}
593	                              value={formData.application_data[field.name] || ""}
594	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
595	                              rows={3}
596	                            />
597	                          ) : field.field_type === "number" ? (
598	                            <Input
599	                              id={`edit-${field.name}`}
600	                              type="number"
601	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
602	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
603	                            />
604	                          ) : field.field_type === "date" ? (
605	                            <Input
606	                              id={`edit-${field.name}`}
607	                              type="date"
608	                              value={formData.application_data[field.name] || ""}
609	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
610	                            />
611	                          ) : (
612	                            <Input
613	                              id={`edit-${field.name}`}
614	                              value={formData.application_data[field.name] || ""}
615	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
616	                            />
617	                          )}
618	                        </div>
619	                      ) : (
620	                        <p>{displayValue}</p>
621	                      )}
622	                    </div>
623	                  );
624	                })}
625	              </CardContent>
626	            </Card>
627	          )}
628	
629	          {/* Notes */}
630	          <Card className="md:col-span-2 lg:col-span-3">
631	            <CardHeader>
632	              <CardTitle>Internal Notes</CardTitle>
633	            </CardHeader>
634	            <CardContent>
635	              {editMode ? (
636	                <div className="space-y-2">
637	                  <Label htmlFor="notes">Notes</Label>
638	                  <Textarea
639	                    id="notes"
640	                    value={formData.notes}
641	                    onChange={handleChange}
642	                    rows={4}
643	                    placeholder="Add internal notes..."
644	                  />
645	                </div>
646	              ) : (
647	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
648	                  {application.notes || "No notes added"}
649	                </p>
650	              )}
651	            </CardContent>
652	          </Card>
653	
654	          {/* Metadata */}
655	          <Card className="md:col-span-2 lg:col-span-3">
656	            <CardHeader>
657	              <CardTitle>Application Details</CardTitle>
658	            </CardHeader>
659	            <CardContent className="grid gap-4 sm:grid-cols-2">
660	              <div>
661	                <Label className="text-xs text-muted-foreground">Created</Label>
662	                <p>{new Date(application.created_at).toLocaleString()}</p>
663	              </div>
664	              <div>
665	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
666	                <p>{new Date(application.updated_at).toLocaleString()}</p>
667	              </div>
668	              <div>
669	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
670	                <p className="font-mono">{application.customer_id}</p>
671	              </div>
672	              <div>
673	                <Label className="text-xs text-muted-foreground">Service ID</Label>
674	                <p className="font-mono">{application.service_id}</p>
675	              </div>
676	            </CardContent>
677	          </Card>
678	        </div>
679	
680	        {/* Document Management Section */}
681	        {shopId && application && (
682	          <div className="mt-8">
683	            <DocumentManager
684	              shopId={shopId}
685	              applicationId={application.id}
686	              canUpload={true}
687	              canVerify={true}
688	              canReject={true}
689	              canDelete={true}
690	              onChecklistUpdated={fetchApplication}
691	            />
692	          </div>
693	        )}
694	
695	        {/* Billing & Payments Section */}
696	        {shopId && application && (
697	          <div className="mt-8">
698	            <BillingManager
699	              shopId={shopId}
700	              applicationId={application.id}
701	              applicationNumber={application.application_number}
702	              serviceName={application.service.name}
703	              serviceBasePrice={application.service.base_price}
704	              customerName={application.customer.name}
705	              canCreate={permissions.canCreateBilling}
706	              canUpdate={permissions.canUpdateBilling}
707	              canDiscount={permissions.canDiscount}
708	              canCharge={permissions.canCharge}
709	              canVoid={permissions.canVoid}
710	              canPaymentCreate={permissions.canPaymentCreate}
711	              canPaymentView={permissions.canPaymentView}
712	              onBillingCreated={fetchApplication}
713	            />
714	          </div>
715	        )}
716	
717	        {editMode && (
718	          <div className="mt-6 flex justify-end gap-3">
719	            <Button variant="outline" onClick={() => {
720	              setFormData({
721	                status: application.status,
722	                assigned_staff_id: application.assigned_staff_id || "",
723	                application_data: application.application_data || {},
724	                notes: application.notes || "",
725	              });
726	              setEditMode(false);
727	            }}>
728	              Cancel
729	            </Button>
730	            <Button onClick={handleSave} disabled={saving}>
731	              <Save className="mr-2 h-4 w-4" />
732	              {saving ? "Saving..." : "Save Changes"}
733	            </Button>
734	          </div>
735	        )}
736	      </div>
737	    </ProtectedRoute>
738	  );
739	}
740	
741	export default function ApplicationDetailPage() {
742	  return <ApplicationDetailContent />;
743	}

