2	
3	import { useState, useEffect, useCallback } from "react";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Label } from "@/components/ui/label";
7	import { Textarea } from "@/components/ui/textarea";
8	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
9	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
10	import { Badge } from "@/components/ui/badge";
11	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
12	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
13	import { formatCurrency } from "@/lib/utils";
14	import { Plus, Edit, Trash2, Save, X, Eye, Receipt, DollarSign,
15	  Minus, AlertCircle, CheckCircle, Loader2, CreditCard, Banknote,
16	  ArrowLeft, ArrowRight, RefreshCw, FileText, Shield, AlertTriangle,
17	  ChevronDown, ChevronUp
18	} from "lucide-react";
19	import {
20	  BillingResponse,
21	  BillingItemResponse,
22	  PaymentResponse,
23	  BillingItemCreate,
24	  BillingItemUpdate,
25	  PaymentCreate,
26	  PaymentFormData,
27	  PaymentMethod,
28	  BillingStatus,
29	  PaymentStatus,
30	  BillingFormData,
31	  PAYMENT_METHOD_LABELS,
32	  PAYMENT_STATUS_LABELS,
33	  BILLING_STATUS_LABELS,
34	  DISCOUNT_TYPE_LABELS,
35	  DiscountType,
36	  BillingCalculationPreview,
37	} from "@/src/types/billing";
38	import { billingApi } from "@/lib/api";
39	
40	interface BillingManagerProps {
41	  shopId: number;
42	  applicationId: number;
43	  applicationNumber: string;
44	  serviceName: string;
45	  serviceBasePrice: number;
46	  customerName: string;
47	  canCreate: boolean;
48	  canUpdate: boolean;
49	  canDiscount: boolean;
50	  canCharge: boolean;
51	  canVoid: boolean;
52	  canPaymentCreate: boolean;
53	  canPaymentView: boolean;
54	  onBillingCreated?: () => void;
55	}
56	
57	export function BillingManager({
58	  shopId,
59	  applicationId,
60	  applicationNumber,
61	  serviceName,
62	  serviceBasePrice,
63	  customerName,
64	  canCreate,
65	  canUpdate,
66	  canDiscount,
67	  canCharge,
68	  canVoid,
69	  canPaymentCreate,
70	  canPaymentView,
71	  onBillingCreated,
72	}: BillingManagerProps) {
73	  const [loading, setLoading] = useState(true);
74	  const [error, setError] = useState<string | null>(null);
75	  const [billing, setBilling] = useState<BillingResponse | null>(null);
76	  const [payments, setPayments] = useState<PaymentResponse[]>([]);
77	  const [saving, setSaving] = useState(false);
78	  const [creating, setCreating] = useState(false);
79	  const [creatingPayment, setCreatingPayment] = useState(false);
80	  const [showCreateDialog, setShowCreateDialog] = useState(false);
81	  const [showEditDialog, setShowEditDialog] = useState(false);
82	  const [showPaymentDialog, setShowPaymentDialog] = useState(false);
83	  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
84	  const [editingItemId, setEditingItemId] = useState<number | null>(null);
85	  const [previewData, setPreviewData] = useState<BillingCalculationPreview | null>(null);
86	
87	  // Form states
88	  const [createForm, setCreateForm] = useState<BillingFormData>({
89	    items: [
90	      {
91	        name: serviceName,
92	        description: `Service: ${serviceName}`,
93	        amount: serviceBasePrice,
94	        is_service_item: true,
95	        service_id: undefined,
96	        sort_order: 0,
97	      },
98	    ],
99	    discount_type: undefined,
100	    discount_value: undefined,
101	    discount_reason: "",
102	    notes: "",
103	  });
104	
105	  const [editForm, setEditForm] = useState<Partial<BillingFormData>>({});
106	
107	  const [itemForm, setItemForm] = useState<BillingItemCreate>({
108	    name: "",
109	    description: "",
110	    amount: 0,
111	    is_service_item: false,
112	    service_id: undefined,
113	    sort_order: 0,
114	  });
115	
116	  const [paymentForm, setPaymentForm] = useState<PaymentFormData>({
117	    amount: 0,
118	    payment_method: "cash",
119	    reference_number: "",
120	    reference_exception: false,
121	    reference_exception_reason: "",
122	    notes: "",
123	  });
124	
125	  const isDigitalPayment = (method: PaymentMethod) =>
126	    method !== "cash";
127	
128	  const requiresReference = (method: PaymentMethod) =>
129	    isDigitalPayment(method);
130	
131	  const fetchBilling = useCallback(async () => {
132	    setLoading(true);
133	    setError(null);
134	    try {
135	      const data = await billingApi.getBilling(shopId, applicationId);
136	      setBilling(data);
137	    } catch (err) {
138	      setError(err instanceof Error ? err.message : "An error occurred");
139	    } finally {
140	      setLoading(false);
141	    }
142	  }, [shopId, applicationId]);
143	
144	  const fetchPayments = useCallback(async () => {
145	    if (!billing) return;
146	    try {
147	      const data = await billingApi.listPayments(shopId, billing.id);
148	      setPayments(data.items);
149	    } catch (err) {
150	      console.error("Failed to fetch payments:", err);
151	    }
152	  }, [shopId, billing]);
153	
154	  useEffect(() => {
155	    fetchBilling();
156	  }, [fetchBilling]);
157	
158	  useEffect(() => {
159	    fetchPayments();
160	  }, [fetchPayments]);
161	
162	  const handlePreviewCalculation = async () => {
163	    if (createForm.items.length === 0) return;
164	    try {
165	      const data = await billingApi.previewBilling(shopId, {
166	        items: createForm.items,
167	        discount_type: createForm.discount_type,
168	        discount_value: createForm.discount_value,
169	      });
170	      setPreviewData(data);
171	      setShowPreviewDialog(true);
172	    } catch (err) {
173	      console.error("Failed to preview calculation:", err);
174	    }
175	  };
176	
177	  const handleCreateBilling = async () => {
178	    if (createForm.items.length === 0) {
179	      setError("At least one line item is required");
180	      return;
181	    }
182	    if (createForm.discount_type && createForm.discount_value && !createForm.discount_reason) {
183	      setError("Discount reason is required");
184	      return;
185	    }
186	    setCreating(true);
187	    setError(null);
188	    try {
189	      const data = await billingApi.createBilling(shopId, applicationId, {
190	        application_id: applicationId,
191	        ...createForm,
192	      });
193	      setBilling(data);
194	      setShowCreateDialog(false);
195	      onBillingCreated?.();
196	    } catch (err) {
197	      setError(err instanceof Error ? err.message : "An error occurred");
198	    } finally {
199	      setCreating(false);
200	    }
201	  };
202	
203	  const handleUpdateBilling = async () => {
204	    if (!billing) return;
205	    setSaving(true);
206	    setError(null);
207	    try {
208	      const data = await billingApi.updateBilling(shopId, billing.id, editForm);
209	      setBilling(data);
210	      setShowEditDialog(false);
211	    } catch (err) {
212	      setError(err instanceof Error ? err.message : "An error occurred");
213	    } finally {
214	      setSaving(false);
215	    }
216	  };
217	
218	  const handleAddItem = async () => {
219	    if (!billing || itemForm.name.trim() === "" || itemForm.amount <= 0) return;
220	    setSaving(true);
221	    try {
222	      const data = await billingApi.addBillingItem(shopId, billing.id, itemForm);
223	      setBilling(prev => prev ? { ...prev, items: [...prev.items, data] } : null);
224	      setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 });
225	    } catch (err) {
226	      setError(err instanceof Error ? err.message : "An error occurred");
227	    } finally {
228	      setSaving(false);
229	    }
230	  };
231	
232	  const handleUpdateItem = async () => {
233	    if (!billing || editingItemId === null) return;
234	    setSaving(true);
235	    try {
236	      const data = await billingApi.updateBillingItem(shopId, billing.id, editingItemId, itemForm);
237	      setBilling(prev => prev ? {
238	        ...prev,
239	        items: prev.items.map(i => i.id === editingItemId ? data : i)
240	      } : null);
241	      setEditingItemId(null);
242	    } catch (err) {
243	      setError(err instanceof Error ? err.message : "An error occurred");
244	    } finally {
245	      setSaving(false);
246	    }
247	  };
248	
249	  const handleDeleteItem = async (itemId: number) => {
250	    if (!billing || !confirm("Delete this line item?")) return;
251	    setSaving(true);
252	    try {
253	      await billingApi.deleteBillingItem(shopId, billing.id, itemId);
254	      setBilling(prev => prev ? { ...prev, items: prev.items.filter(i => i.id !== itemId) } : null);
255	    } catch (err) {
256	      setError(err instanceof Error ? err.message : "An error occurred");
257	    } finally {
258	      setSaving(false);
259	    }
260	  };
261	
262	  const startEditItem = (item: BillingItemResponse) => {
263	    setItemForm({
264	      name: item.name,
265	      description: item.description || "",
266	      amount: item.amount,
267	      is_service_item: item.is_service_item,
268	      service_id: item.service_id,
269	      sort_order: item.sort_order,
270	    });
271	    setEditingItemId(item.id);
272	  };
273	
274	  const handleCreatePayment = async () => {
275	    if (!billing) return;
276	    if (paymentForm.amount <= 0) {
277	      setError("Payment amount must be greater than zero");
278	      return;
279	    }
280	    if (paymentForm.amount > (billing.balance_amount || 0)) {
281	      setError("Payment amount exceeds outstanding balance");
282	      return;
283	    }
284	    if (requiresReference(paymentForm.payment_method) && !paymentForm.reference_exception && !paymentForm.reference_number?.trim()) {
285	      setError("Reference number is required for digital payments");
286	      return;
287	    }
288	    if (paymentForm.reference_exception && !paymentForm.reference_exception_reason?.trim()) {
289	      setError("Exception reason is required when reference is unavailable");
290	      return;
291	    }
292	    setCreatingPayment(true);
293	    setError(null);
294	    try {
295	      const data = await billingApi.createPayment(shopId, billing.id, paymentForm);
296	      setPayments(prev => [...prev, data]);
297	      setBilling(prev => prev ? {
298	        ...prev,
299	        amount_paid: data.amount + (prev.amount_paid || 0),
300	        balance_amount: Math.max(0, (prev.balance_amount || 0) - data.amount),
301	        payment_status: data.amount + (prev.amount_paid || 0) >= (prev.total_amount || 0) ? "paid" :
302	          data.amount + (prev.amount_paid || 0) > 0 ? "partially_paid" : "unpaid",
303	      } : null);
304	      setShowPaymentDialog(false);
305	      setPaymentForm({ amount: 0, payment_method: "cash", reference_number: "", reference_exception: false, reference_exception_reason: "", notes: "" });
306	    } catch (err) {
307	      setError(err instanceof Error ? err.message : "An error occurred");
308	    } finally {
309	      setCreatingPayment(false);
310	    }
311	  };
312	
313	  const handleIssueBilling = async () => {
314	    if (!billing || !confirm("Issue this billing? This will change status from Draft to Issued.")) return;
315	    setSaving(true);
316	    try {
317	      const data = await billingApi.issueBilling(shopId, billing.id);
318	      setBilling(data);
319	    } catch (err) {
320	      setError(err instanceof Error ? err.message : "An error occurred");
321	    } finally {
322	      setSaving(false);
323	    }
324	  };
325	
326	  const handleVoidBilling = async () => {
327	    if (!billing || !confirm("Void this billing? This action cannot be undone.")) return;
328	    setSaving(true);
329	    try {
330	      const data = await billingApi.voidBilling(shopId, billing.id);
331	      setBilling(data);
332	    } catch (err) {
333	      setError(err instanceof Error ? err.message : "An error occurred");
334	    } finally {
335	      setSaving(false);
336	    }
337	  };
338	
339	  const getStatusBadge = (status: string, type: "billing" | "payment") => {
340	    if (type === "billing") {
341	      const config: Record<BillingStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
342	        draft: { variant: "secondary", label: "Draft" },
343	        issued: { variant: "default", label: "Issued" },
344	        void: { variant: "destructive", label: "Void" },
345	      };
346	      const c = config[status as BillingStatus] || { variant: "secondary", label: status };
347	      return <Badge variant={c.variant}>{c.label}</Badge>;
348	    } else {
349	      const config: Record<PaymentStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
350	        unpaid: { variant: "destructive", label: "Unpaid" },
351	        partially_paid: { variant: "warning", label: "Partially Paid" },
