1	/**
2	 * Lightweight API client for the backend.
3	 *
4	 * - Auth requests are proxied through Next.js API routes so the browser never
5	 *   talks directly to the backend and HTTP-only cookies flow through the proxy.
6	 * - Access tokens are held **only** in memory (never localStorage/sessionStorage)
7	 *   to limit XSS exposure.
8	 */
9	
10	let accessToken: string | null = null;
11	let accessTokenExpiry: number | null = null;
12	
13	export function setAccessToken(token: string, expiresIn: number) {
14	  accessToken = token;
15	  // Set expiry slightly earlier to avoid using an about-to-expire token.
16	  accessTokenExpiry = Date.now() + (expiresIn - 30) * 1000;
17	}
18	
19	export function clearAccessToken() {
20	  accessToken = null;
21	  accessTokenExpiry = null;
22	}
23	
24	export function getAccessToken(): string | null {
25	  if (!accessToken || !accessTokenExpiry) return null;
26	  if (Date.now() >= accessTokenExpiry) return null;
27	  return accessToken;
28	}
29	
30	// Base URL for Next.js API proxy routes (same origin).
31	const AUTH_PROXY = "/api/auth";
32	
33	// Base URL for API calls via Next.js rewrites proxy to backend.
34	// Uses /api/v1 which is rewritten to http://backend:8000/api/v1 by next.config.mjs
35	const API_BASE =
36	  process.env.NEXT_PUBLIC_API_BASE_URL ?? "/api/v1";
37	
38	/** Authenticated fetch against the backend API. */
39	export async function apiFetch(
40	  path: string,
41	  init: RequestInit = {}
42	): Promise<Response> {
43	  const headers = new Headers(init.headers);
44	  const token = getAccessToken();
45	  if (token) {
46	    headers.set("Authorization", `Bearer ${token}`);
47	  }
48	  headers.set("Content-Type", "application/json");
49	  return fetch(`${API_BASE}${path}`, { ...init, headers, credentials: "include" });
50	}
51	
52	// ── Types ────────────────────────────────────────────────────────────────────
53	
54	export interface Shop {
55	  id: number;
56	  code: string;
57	  name: string;
58	  slug: string;
59	  status: "active" | "inactive" | "suspended";
60	  created_at: string;
61	  updated_at: string;
62	  primary_owner?: {
63	    id: number;
64	    email: string;
65	    full_name: string;
66	  } | null;
67	}
68	
69	export interface ShopListResponse {
70	  items: Shop[];
71	  total: number;
72	  page: number;
73	  page_size: number;
74	  total_pages: number;
75	}
76	
77	export interface CreateShopPayload {
78	  name: string;
79	  slug: string;
80	  owner_user_id?: number;
81	}
82	
83	export interface UpdateShopPayload {
84	  name?: string;
85	  slug?: string;
86	}
87	
88	export interface ShopManager {
89	  id: number;
90	  user_id: number;
91	  shop_id: number;
92	  is_active: boolean;
93	  created_at: string;
94	  updated_at: string;
95	  user: {
96	    id: number;
97	    email: string;
98	    full_name: string;
99	    platform_role: string;
100	  };
101	}
102	
103	export interface StaffMember {
104	  membership_id: number;
105	  user_id: number;
106	  shop_id: number;
107	  role: "shop_owner" | "shop_manager" | "staff" | "financial_staff";
108	  is_active: boolean;
109	  created_at: string;
110	  updated_at: string;
111	  user_email: string;
112	  user_name: string;
113	}
114	
115	export interface StaffListResponse {
116	  items: StaffMember[];
117	  total: number;
118	  page: number;
119	  page_size: number;
120	  total_pages: number;
121	}
122	
123	export interface CreateStaffPayload {
124	  email: string;
125	  full_name: string;
126	  password: string;
127	  role: "shop_manager" | "staff" | "financial_staff";
128	}
129	
130	export interface UpdateStaffPayload {
131	  full_name?: string;
132	}
133	
134	export interface ChangeStaffRolePayload {
135	  role: "shop_owner" | "shop_manager" | "staff" | "financial_staff";
136	}
137	
138	export interface PaginatedParams {
139	  page?: number;
140	  page_size?: number;
141	  search?: string;
142	  role?: string;
143	  status?: string;
144	  is_active?: boolean;
145	}
146	
147	// ── Auth API (proxied through Next.js for cookie management) ──────────────
148	
149	export interface AuthUser {
150	  id: number;
151	  email: string;
152	  full_name: string;
153	  platform_role: string | null;
154	  is_active: boolean;
155	  created_at: string;
156	  updated_at: string;
157	}
158	
159	export interface LoginResponse {
160	  access_token: string;
161	  token_type: string;
162	  expires_in: number;
163	  user: AuthUser;
164	}
165	
166	export async function login(
167	  email: string,
168	  password: string
169	): Promise<LoginResponse> {
170	  const res = await fetch(`${AUTH_PROXY}/login`, {
171	    method: "POST",
172	    headers: { "Content-Type": "application/json" },
173	    body: JSON.stringify({ email, password }),
174	    credentials: "include",
175	  });
176	  if (!res.ok) {
177	    const body = await res.json().catch(() => ({}));
178	    throw new ApiError(res.status, body?.error?.message ?? "Login failed");
179	  }
180	  const data: LoginResponse = await res.json();
181	  setAccessToken(data.access_token, data.expires_in);
182	  return data;
183	}
184	
185	export async function refreshToken(): Promise<LoginResponse | null> {
186	  const res = await fetch(`${AUTH_PROXY}/refresh`, {
187	    method: "POST",
188	    credentials: "include",
189	  });
190	  if (!res.ok) return null;
191	  const data: LoginResponse = await res.json();
192	  setAccessToken(data.access_token, data.expires_in);
193	  return data;
194	}
195	
196	export async function logout(): Promise<void> {
197	  await fetch(`${AUTH_PROXY}/logout`, {
198	    method: "POST",
199	    credentials: "include",
200	    headers: accessToken
201	      ? { Authorization: `Bearer ${accessToken}` }
202	      : undefined,
203	  });
204	  clearAccessToken();
205	}
206	
207	export async function fetchCurrentUser(): Promise<AuthUser> {
208	  const token = getAccessToken();
209	  if (!token) throw new ApiError(401, "Not authenticated");
210	  const res = await fetch(`${AUTH_PROXY}/me`, {
211	    headers: { Authorization: `Bearer ${token}` },
212	    credentials: "include",
213	  });
214	  if (!res.ok) throw new ApiError(res.status, "Failed to load user");
215	  return res.json();
216	}
217	
218	export class ApiError extends Error {
219	  status: number;
220	  constructor(status: number, message: string) {
221	    super(message);
222	    this.name = "ApiError";
223	    this.status = status;
224	  }
225	}
226	
227	// ── Platform Shops API ──────────────────────────────────────────────────────
228	
229	export const platformApi = {
230	  /** List shops with search, status filter, pagination */
231	  async listShops(params: PaginatedParams = {}): Promise<ShopListResponse> {
232	    const searchParams = new URLSearchParams();
233	    if (params.page) searchParams.set("page", String(params.page));
234	    if (params.page_size) searchParams.set("page_size", String(params.page_size));
235	    if (params.search) searchParams.set("search", params.search);
236	    if (params.status) searchParams.set("status", params.status);
237	    const res = await apiFetch(`/platform/shops?${searchParams.toString()}`);
238	    if (!res.ok) throw new ApiError(res.status, "Failed to list shops");
239	    return res.json();
240	  },
241	
242	  /** Create a new shop */
243	  async createShop(payload: CreateShopPayload): Promise<Shop> {
244	    const res = await apiFetch("/platform/shops", {
245	      method: "POST",
246	      body: JSON.stringify(payload),
247	    });
248	    if (!res.ok) {
249	      const body = await res.json().catch(() => ({}));
250	      throw new ApiError(res.status, body?.error?.message ?? "Failed to create shop");
251	    }
252	    return res.json();
253	  },
254	
255	  /** Get shop by ID */
256	  async getShop(shopId: number): Promise<Shop> {
257	    const res = await apiFetch(`/platform/shops/${shopId}`);
258	    if (!res.ok) throw new ApiError(res.status, "Failed to fetch shop");
259	    return res.json();
260	  },
261	
262	  /** Update shop name/slug */
263	  async updateShop(shopId: number, payload: UpdateShopPayload): Promise<Shop> {
264	    const res = await apiFetch(`/platform/shops/${shopId}`, {
265	      method: "PATCH",
266	      body: JSON.stringify(payload),
267	    });
268	    if (!res.ok) throw new ApiError(res.status, "Failed to update shop");
269	    return res.json();
270	  },
271	
272	  /** Activate a shop */
273	  async activateShop(shopId: number): Promise<Shop> {
274	    const res = await apiFetch(`/platform/shops/${shopId}/activate`, {
275	      method: "POST",
276	      body: JSON.stringify({}),
277	    });
278	    if (!res.ok) throw new ApiError(res.status, "Failed to activate shop");
279	    return res.json();
280	  },
281	
282	  /** Deactivate or suspend a shop */
283	  async deactivateShop(shopId: number, status: "inactive" | "suspended" = "inactive"): Promise<Shop> {
284	    const res = await apiFetch(`/platform/shops/${shopId}/deactivate`, {
285	      method: "POST",
286	      body: JSON.stringify({ status }),
287	    });
288	    if (!res.ok) throw new ApiError(res.status, "Failed to deactivate shop");
289	    return res.json();
290	  },
291	
