/* =============================================================================
   Receipt & Communication API (Phase 10)
   ============================================================================= */

export type ReceiptType = "invoice" | "payment_receipt";
export type ReceiptStatus = "generated" | "failed" | "regenerated";

export type CommunicationChannel = "email" | "whatsapp" | "sms";
export type CommunicationStatus = "pending" | "queued" | "sent" | "failed" | "cancelled";

export interface ReceiptResponse {
  id: number;
  shop_id: number;
  billing_id?: number;
  payment_id?: number;
  receipt_number: string;
  receipt_type: ReceiptType;
  storage_key?: string;
  status: ReceiptStatus;
  generated_at: string;
  generated_by: number;
  created_at: string;
  updated_at?: string;
}

export interface CommunicationHistoryResponse {
  id: number;
  shop_id: number;
  customer_id?: number;
  application_id?: number;
  payment_id?: number;
  billing_id?: number;
  receipt_id?: number;
  channel: CommunicationChannel;
  recipient: string;
  subject?: string;
  status: CommunicationStatus;
  provider?: string;
  provider_message_id?: string;
  error_message?: string;
  sent_at?: string;
  created_at: string;
  updated_at?: string;
