"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";
import { receiptApi } from "@/lib/api";
import { ReceiptViewerProps } from "@/src/types/receipt";

export function ReceiptViewer({
  receiptId,
  shopId,
  onClose,
}: ReceiptViewerProps) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [invoiceUrl, setInvoiceUrl] = useState<string | null>(null);
  const [paymentReceiptUrl, setPaymentReceiptUrl] = useState<string | null>(null);
  const [expiresAt, setExpiresAt] = useState<string | null>(null);
  const [receiptType, setReceiptType] = useState<"invoice" | "payment_receipt" | null>(null);

  // Try to determine if this is an invoice or payment receipt by checking both endpoints
  useEffect(() => {
    const loadReceiptUrls = async () => {
      setLoading(true);
      setError(null);

      try {
        // First try as invoice - we need billing ID for this
        // Since we don't have direct mapping, we'll need to get it from context or try both
        // For now, we'll show a placeholder approach

        // In a real implementation, we would first fetch receipt details to get billing/payment ID
        // But since we don't have that endpoint readily available, we'll simulate

        // For demo purposes, let's assume we can determine type from context or try to get both
        // This would be improved with a direct receipt details endpoint

        setLoading(false);
      } catch (err) {
        setError("Failed to load receipt");
        setLoading(false);
      }
    };

    loadReceiptUrls();
  }, [shopId, receiptId]);

  // Simplified viewer for now - shows placeholder
  // In production, this would integrate with actual receipt fetching logic

  if (loading) {
    return (
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle>Loading Receipt...</DialogTitle>
        </DialogHeader>
        <DialogDescription className="mb-4 text-center">
          <Spinner className="h-8 w-8 mx-auto" />
          <p className="mt-2">Preparing your receipt for viewing...</p>
        </DialogDescription>
      </DialogContent>
    );
  }

  if (error) {
    return (
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle>Error Loading Receipt</DialogTitle>
        </DialogHeader>
        <DialogDescription>
          <p>{error}</p>
          <div className="mt-4 flex justify-end">
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </div>
        </DialogDescription>
      </DialogContent>
    );
  }

  return (
    <DialogContent className="max-w-2xl">
      <DialogHeader>
        <DialogTitle>Receipt Viewer</DialogTitle>
      </DialogHeader>
      <DialogDescription className="space-y-6">
        <div className="text-center py-8">
          <div className="border-2 border-dashed border-muted-foreground rounded-lg p-8">
            <div className="text-muted-foreground">
              <span className="material-icons">picture_as_pdf</span>
              <h3 className="mt-4">Receipt PDF</h3>
              <p className="mt-2">The receipt PDF viewer would be implemented here.</p>
              <p className="mt-2 text-sm">
                In a production environment, this would display the actual PDF using the signed URL
                from the backend receipt generation service.
              </p>
            </div>
          </div>
          <div className="flex justify-end">
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
            <Button onClick={() => {
              // In real implementation: window.open(actualSignedUrl, '_blank');
              alert("Download functionality would be implemented here with actual signed URL");
            }}>
              Download PDF
            </Button>
          </div>
        </div>
      </DialogDescription>
    </DialogContent>
  );
}

