                    <Button variant="outline" onClick={() => setShowDetails(false)}>
                      Close
                    </Button>
                  </DialogDescription>
                </DialogContent>
              </Dialog>
            )}
          </>
        )}
      </DialogDescription>
      <DialogDescription className="flex justify-end">
        <Button variant="outline" onClick={onClose}>
          Close
        </Button>
      </DialogDescription>
    </DialogContent>
  );
}

